CREATE FUNCTION public.get_category_ancestors(p_category_id integer) RETURNS TABLE(id integer, name_en character varying, slug character varying, level integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH RECURSIVE ancestors AS (
        SELECT 
            ch.id,
            ch.parent_id,
            ch.name_en,
            ch.slug,
            ch.level
        FROM category_hierarchy ch
        WHERE ch.id = p_category_id
        
        UNION ALL
        
        SELECT 
            ch.id,
            ch.parent_id,
            ch.name_en,
            ch.slug,
            ch.level
        FROM category_hierarchy ch
        JOIN ancestors a ON ch.id = a.parent_id
    )
    SELECT a.id, a.name_en, a.slug, a.level
    FROM ancestors a
    ORDER BY a.level;
END;
$$;


