--
-- Name: get_category_attributes_inherited(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_category_attributes_inherited(p_category_id integer) RETURNS TABLE(attribute_id integer, name_en character varying, name_am character varying, name_om character varying, name_ti character varying, slug character varying, data_type character varying, validation_rules jsonb, unit character varying, is_required boolean, is_filterable boolean, is_searchable boolean, is_inherited boolean, display_order integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_path VARCHAR;
    v_ancestor_ids INT[];
BEGIN
    -- Get path of target category
    SELECT path INTO v_path
    FROM category_hierarchy
    WHERE id = p_category_id;
    
    IF v_path IS NOT NULL AND v_path != '' THEN
        -- Convert '/1/5/12/' into integer array [1, 5, 12]
        v_ancestor_ids := string_to_array(trim(both '/' from v_path), '/')::int[];
    ELSE
        v_ancestor_ids := ARRAY[p_category_id];
    END IF;

    RETURN QUERY
    WITH candidate_attributes AS (
        SELECT 
            ad.id AS attribute_id,
            ad.name_en,
            ad.name_am,
            ad.name_om,
            ad.name_ti,
            ad.slug,
            ad.data_type,
            ad.validation_rules,
            ad.unit,
            ca.is_required,
            ad.is_filterable,
            ad.is_searchable,
            (ca.category_id != p_category_id) AS is_inherited,
            ca.display_order,
            ca.category_id AS assigned_category_id,
            ROW_NUMBER() OVER (
                PARTITION BY ad.id 
                ORDER BY 
                    -- Prefer exact category assignment over ancestor assignments
                    CASE WHEN ca.category_id = p_category_id THEN 0 ELSE 1 END,
                    ca.display_order ASC
            ) AS rn
        FROM category_attributes ca
        JOIN attribute_definitions ad ON ad.id = ca.attribute_id
        WHERE ca.category_id = ANY(v_ancestor_ids) 
           OR ca.category_id = p_category_id
    )
    SELECT 
        ca.attribute_id,
        ca.name_en,
        ca.name_am,
        ca.name_om,
        ca.name_ti,
        ca.slug,
        ca.data_type,
        ca.validation_rules,
        ca.unit,
        ca.is_required,
        ca.is_filterable,
        ca.is_searchable,
        ca.is_inherited,
        ca.display_order
    FROM candidate_attributes ca
    WHERE ca.rn = 1
    ORDER BY ca.display_order ASC, ca.attribute_id ASC;
END;
$$;


ALTER FUNCTION public.get_category_attributes_inherited(p_category_id integer) OWNER TO postgres;

