CREATE FUNCTION public.get_category_descendants_by_term(p_term text) RETURNS TABLE(id integer)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_cat_id INT;
BEGIN
    v_cat_id := resolve_category_by_alias(p_term);
