--
-- Name: normalize_query(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.normalize_query(p_query text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_normalized TEXT;
BEGIN
    IF p_query IS NULL THEN
        RETURN '';
    END IF;

    -- 1. Lowercase
    v_normalized := LOWER(TRIM(p_query));
    
    -- 2. Preserve ASCII alphanumeric, Ethiopic Unicode (\u1200-\u137F), 
    --    apostrophes (Afaan Oromoo hudhaa), spaces, and hyphens.
    v_normalized := REGEXP_REPLACE(v_normalized, '[^a-z0-9\u1200-\u137F\s\''-]', '', 'g');
    
    -- 3. Consolidate multiple spaces
    v_normalized := REGEXP_REPLACE(v_normalized, '\s+', ' ', 'g');
    
    -- 4. Trim
    RETURN TRIM(v_normalized);
END;
$$;


ALTER FUNCTION public.normalize_query(p_query text) OWNER TO postgres;

