--
-- Name: recalculate_all_ratings(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recalculate_all_ratings() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    updated_count INT;
BEGIN
    WITH rating_updates AS (
        SELECT
            seller_id,
            ROUND(AVG(rating)::NUMERIC, 2) as new_rating
        FROM seller_reviews
        GROUP BY seller_id
    )
    UPDATE users u
    SET rating = ru.new_rating
    FROM rating_updates ru
    WHERE u.id = ru.seller_id
      AND u.role = 'seller'
    RETURNING u.id INTO updated_count;

    RETURN updated_count;
END;
$$;


ALTER FUNCTION public.recalculate_all_ratings() OWNER TO postgres;

