CREATE FUNCTION public.record_tier_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (OLD.tier IS DISTINCT FROM NEW.tier) OR (OLD.buyer_tier IS DISTINCT FROM NEW.buyer_tier) THEN
        INSERT INTO user_tier_history (user_id, tier_type, old_tier, new_tier, reason)
        VALUES (
            NEW.id,
            CASE WHEN OLD.tier IS DISTINCT FROM NEW.tier THEN 'seller' ELSE 'buyer' END,
            COALESCE(CASE WHEN OLD.tier IS DISTINCT FROM NEW.tier THEN OLD.tier::text ELSE OLD.buyer_tier::text END, 'normal'),
            COALESCE(CASE WHEN OLD.tier IS DISTINCT FROM NEW.tier THEN NEW.tier::text ELSE NEW.buyer_tier::text END, 'normal'),
            'system'
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.record_tier_change() OWNER TO postgres;

--
-- Name: refresh_all_materialized_views(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_all_materialized_views() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    refresh_log TEXT := '';
BEGIN
    -- Refresh seller rating stats
    REFRESH MATERIALIZED VIEW CONCURRENTLY seller_rating_stats;
    refresh_log := refresh_log || 'seller_rating_stats refreshed; ';

    -- Refresh user warning counts
    REFRESH MATERIALIZED VIEW CONCURRENTLY user_warning_counts;
    refresh_log := refresh_log || 'user_warning_counts refreshed; ';

    -- Refresh marketplace listings (created in 015)
    BEGIN
        REFRESH MATERIALIZED VIEW CONCURRENTLY marketplace_listings;
        refresh_log := refresh_log || 'marketplace_listings refreshed; ';
    EXCEPTION
        WHEN undefined_table THEN
            refresh_log := refresh_log || 'marketplace_listings not yet created; ';
    END;

    RETURN refresh_log || 'All views refreshed successfully';
EXCEPTION
    WHEN OTHERS THEN
        RETURN 'Error refreshing views: ' || SQLERRM;
END;
$$;


ALTER FUNCTION public.refresh_all_materialized_views() OWNER TO postgres;

--
-- Name: FUNCTION refresh_all_materialized_views(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.refresh_all_materialized_views() IS 'Refreshes all materialized views (use in cron job)';


--
-- Name: resolve_category_by_alias(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_category_by_alias(p_term text) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_cat_id INT;
    v_clean_term TEXT;
BEGIN
    v_clean_term := LOWER(TRIM(p_term));
    IF v_clean_term = '' THEN
        RETURN NULL;
    END IF;

    -- 1. Check exact match in category_aliases
    SELECT category_id INTO v_cat_id
    FROM category_aliases
    WHERE LOWER(alias) = v_clean_term
    LIMIT 1;

    IF v_cat_id IS NOT NULL THEN
        RETURN v_cat_id;
    END IF;

    -- 2. Check exact slug or name matches in category_hierarchy
    SELECT id INTO v_cat_id
    FROM category_hierarchy
    WHERE is_active = true
      AND (
          LOWER(slug) = v_clean_term
          OR LOWER(name_en) = v_clean_term
          OR LOWER(name_am) = v_clean_term
          OR LOWER(name_om) = v_clean_term
          OR LOWER(name_ti) = v_clean_term
      )
    ORDER BY level DESC  -- prefer most specific leaf
    LIMIT 1;

    RETURN v_cat_id;
END;
$$;


ALTER FUNCTION public.resolve_category_by_alias(p_term text) OWNER TO postgres;

--
-- Name: set_product_expiration(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_product_expiration() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    user_tier VARCHAR(20);
    expiry_days INT;
BEGIN
    -- Get seller tier
    SELECT tier::text INTO user_tier FROM users WHERE id = NEW.seller_id;

    -- Set expiration based on tier (if not manually set)
    IF NEW.expires_at IS NULL THEN
        CASE user_tier
            WHEN 'premium' THEN expiry_days := 90;
            WHEN 'gold' THEN expiry_days := 60;
            WHEN 'normal' THEN expiry_days := 30;
            ELSE expiry_days := 30;
        END CASE;

        NEW.expires_at := NOW() + (expiry_days || ' days')::INTERVAL;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.set_product_expiration() OWNER TO postgres;

--
-- Name: FUNCTION set_product_expiration(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.set_product_expiration() IS 'Automatically sets product expiration date based on seller tier';


