--
-- Name: sync_brand_to_dictionary(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_brand_to_dictionary() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO brand_dictionary (name, normalized_name, aliases, category_ids, is_active)
    VALUES (
        NEW.name,
        normalize_query(NEW.name),
        jsonb_build_array(LOWER(NEW.slug)),
        NEW.category_ids,
        NEW.is_active
    )
    ON CONFLICT (name) DO UPDATE 
    SET 
        normalized_name = EXCLUDED.normalized_name,
        category_ids = EXCLUDED.category_ids,
        is_active = EXCLUDED.is_active,
        updated_at = NOW();
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_brand_to_dictionary() OWNER TO postgres;

--
-- Name: sync_otp_codes_columns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_otp_codes_columns() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.code != '' AND (NEW.code_encrypted IS NULL OR NEW.code_encrypted = '') THEN
        NEW.code_encrypted := NEW.code;
    ELSIF NEW.code_encrypted != '' AND (NEW.code IS NULL OR NEW.code = '') THEN
        NEW.code := NEW.code_encrypted;
    END IF;

    IF NEW.used = TRUE AND NEW.status = 'pending' THEN
        NEW.status := 'verified';
    ELSIF NEW.status = 'verified' AND NEW.used = FALSE THEN
        NEW.used := TRUE;
    END IF;

    IF NEW.locked_until IS NOT NULL AND NEW.locked_until > NOW() THEN
        NEW.status := 'locked';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_otp_codes_columns() OWNER TO postgres;

