--
-- Name: update_category_hierarchy_path(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_category_hierarchy_path() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_parent_path VARCHAR;
    v_parent_level INT;
BEGIN
    -- Check 1: Direct self-parenting
    IF NEW.parent_id IS NOT NULL AND NEW.parent_id = NEW.id THEN
        RAISE EXCEPTION 'Category cannot be its own parent (id: %)', NEW.id;
    END IF;

    IF NEW.parent_id IS NULL THEN
        NEW.level := 0;
        NEW.path := '/' || CAST(NEW.id AS VARCHAR) || '/';
    ELSE
        SELECT level, path
        INTO v_parent_level, v_parent_path
        FROM category_hierarchy
        WHERE id = NEW.parent_id
        FOR SHARE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Parent category ID % does not exist', NEW.parent_id;
        END IF;

        -- Check 2: Circular ancestry prevention
        -- In an UPDATE, the parent cannot be a descendant of NEW.id
        IF TG_OP = 'UPDATE' AND (v_parent_path LIKE '%/' || CAST(NEW.id AS VARCHAR) || '/%' OR v_parent_path LIKE '/' || CAST(NEW.id AS VARCHAR) || '/%') THEN
            RAISE EXCEPTION 'Circular hierarchy detected: parent category % is a descendant of category %', NEW.parent_id, NEW.id;
        END IF;

        -- Level constraint check (< 20)
        IF v_parent_level + 1 >= 20 THEN
            RAISE EXCEPTION 'Maximum hierarchy depth exceeded (max 20, attempted: %)', v_parent_level + 1;
        END IF;

        NEW.level := v_parent_level + 1;
        NEW.path := v_parent_path || CAST(NEW.id AS VARCHAR) || '/';
    END IF;

    NEW.updated_at := NOW();
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.update_category_hierarchy_path() OWNER TO postgres;

--
-- Name: update_location_hierarchy_path(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_location_hierarchy_path() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_path VARCHAR(500);
    parent_level INT;
BEGIN
    IF NEW.parent_id IS NULL THEN
        NEW.level := 0;
        NEW.path := '/' || NEW.id || '/';
    ELSE
        SELECT path, level INTO parent_path, parent_level
        FROM location_hierarchy
        WHERE id = NEW.parent_id;
        
        IF parent_path IS NULL THEN
            NEW.level := 1;
            NEW.path := '/' || NEW.parent_id || '/' || NEW.id || '/';
        ELSE
            NEW.level := parent_level + 1;
            NEW.path := parent_path || NEW.id || '/';
        END IF;
    END IF;
    
    NEW.updated_at := NOW();
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.update_location_hierarchy_path() OWNER TO postgres;

