--
-- Name: update_seller_rating(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_seller_rating() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Update seller average rating
    UPDATE users
    SET rating = (
        SELECT ROUND(AVG(rating)::NUMERIC, 2)
        FROM seller_reviews
        WHERE seller_id = NEW.seller_id
    )
    WHERE id = NEW.seller_id;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.update_seller_rating() OWNER TO postgres;

