-- Name: user_has_capability(integer, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.user_has_capability(p_user_id integer, p_capability character varying) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM user_capabilities
        WHERE user_id = p_user_id
          AND capability = p_capability
          AND status = 'active'
    );
END;
$$;


