--

CREATE TABLE public.products (
    id integer NOT NULL,
    seller_id integer NOT NULL,
    location_id integer,
    title character varying(200) DEFAULT ''::character varying NOT NULL,
    price numeric(12,2) DEFAULT 0 NOT NULL,
    description text,
    category_id integer,
    subcategory character varying(100) DEFAULT ''::character varying,
    item character varying(100) DEFAULT ''::character varying,
    condition public.product_condition DEFAULT 'good'::public.product_condition NOT NULL,
    status public.product_status DEFAULT 'pending'::public.product_status NOT NULL,
    admin_notes text,
    reviewed_by integer,
    reviewed_at timestamp with time zone,
    view_count integer DEFAULT 0 NOT NULL,
    contact_count integer DEFAULT 0 NOT NULL,
    expires_at timestamp with time zone,
    sold_at timestamp with time zone,
    kebele character varying(100) DEFAULT NULL::character varying,
    specific_area text,
    latitude numeric(10,7) DEFAULT NULL::numeric,
    longitude numeric(10,7) DEFAULT NULL::numeric,
    listing_duration_days integer,
    startup_fee_percent numeric(5,2) DEFAULT NULL::numeric,
    weekly_increment_percent numeric(5,2) DEFAULT NULL::numeric,
    total_fee_percent numeric(5,2) DEFAULT NULL::numeric,
    total_fee_amount numeric(12,2) DEFAULT NULL::numeric,
    fee_paid boolean DEFAULT false NOT NULL,
    fee_payment_pending boolean DEFAULT false NOT NULL,
    fee_paid_at timestamp with time zone,
    seller_tier_snapshot character varying(10) DEFAULT 'normal'::character varying NOT NULL,
    access_tier character varying(10) DEFAULT NULL::character varying,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    search_vector tsvector GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, (((COALESCE(title, ''::character varying))::text || ' '::text) || COALESCE(description, ''::text)))) STORED,
    listing_type public.listing_type DEFAULT 'sale'::public.listing_type NOT NULL,
    rental_price numeric(12,2),
    rental_duration_value integer,
    rental_duration_unit public.rental_duration_unit,
    deposit_amount numeric(12,2) DEFAULT 0,
    available_from date,
    available_until date,
    is_currently_rented boolean DEFAULT false,
    current_tenant_id integer,
    rented_until date,
    rental_price_per_month numeric(12,2),
    rental_min_duration_months integer,
    rental_max_duration_months integer,
    rental_deposit_amount numeric(12,2),
    rental_terms text,
    available_from_ts timestamp with time zone,
    category_hierarchy_id integer,
    location_hierarchy_id integer,
    brand_id integer,
    product_model_id integer,
    custom_model_name character varying(200),
    CONSTRAINT check_rental_fields CHECK ((((listing_type = 'sale'::public.listing_type) AND (rental_price IS NULL) AND (rental_duration_value IS NULL)) OR ((listing_type = 'rent'::public.listing_type) AND (rental_price IS NOT NULL) AND (rental_duration_value IS NOT NULL)))),
    CONSTRAINT products_access_tier_check CHECK (((access_tier IS NULL) OR ((access_tier)::text = ANY ((ARRAY['gold'::character varying, 'premium'::character varying])::text[])))),
    CONSTRAINT products_deposit_amount_check CHECK ((deposit_amount >= (0)::numeric)),
    CONSTRAINT products_latitude_check CHECK (((latitude IS NULL) OR ((latitude >= ('-90'::integer)::numeric) AND (latitude <= (90)::numeric)))),
    CONSTRAINT products_longitude_check CHECK (((longitude IS NULL) OR ((longitude >= ('-180'::integer)::numeric) AND (longitude <= (180)::numeric)))),
    CONSTRAINT products_price_check CHECK (((price > (0)::numeric) AND (price <= 999999999.99))),
    CONSTRAINT products_rental_deposit_check CHECK (((rental_deposit_amount IS NULL) OR (rental_deposit_amount >= (0)::numeric))),
    CONSTRAINT products_rental_duration_value_check CHECK (((rental_duration_value IS NULL) OR (rental_duration_value > 0))),
    CONSTRAINT products_rental_max_duration_check CHECK (((rental_max_duration_months IS NULL) OR (rental_max_duration_months >= rental_min_duration_months))),
    CONSTRAINT products_rental_min_duration_check CHECK (((rental_min_duration_months IS NULL) OR (rental_min_duration_months >= 1))),
    CONSTRAINT products_rental_price_check CHECK (((rental_price IS NULL) OR ((rental_price > (0)::numeric) AND (rental_price <= 999999999.99)))),
    CONSTRAINT products_seller_tier_snapshot_check CHECK (((seller_tier_snapshot)::text = ANY ((ARRAY['normal'::character varying, 'gold'::character varying, 'premium'::character varying])::text[])))
);


