--
-- Name: category_applicable_attributes; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.category_applicable_attributes AS
 SELECT ca.category_id,
    ch.name_en AS category_name,
    ch.slug AS category_slug,
    ad.id AS attribute_id,
    ad.name_en AS attribute_name,
    ad.slug AS attribute_slug,
    ad.data_type,
    ad.validation_rules,
    ad.unit,
    ca.is_required,
    ca.display_order,
    ad.is_filterable,
    ad.is_searchable
   FROM ((public.category_attributes ca
     JOIN public.category_hierarchy ch ON ((ch.id = ca.category_id)))
     JOIN public.attribute_definitions ad ON ((ad.id = ca.attribute_id)))
  ORDER BY ca.category_id, ca.display_order;


