--
-- Name: category_breadcrumbs; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.category_breadcrumbs AS
 WITH RECURSIVE category_path AS (
         SELECT category_hierarchy.id,
            category_hierarchy.parent_id,
            category_hierarchy.name_en,
            category_hierarchy.slug,
            category_hierarchy.level,
            category_hierarchy.path,
            ARRAY[(category_hierarchy.name_en)::text] AS breadcrumb_names,
            ARRAY[(category_hierarchy.slug)::text] AS breadcrumb_slugs,
            ARRAY[category_hierarchy.id] AS breadcrumb_ids
           FROM public.category_hierarchy
          WHERE (category_hierarchy.parent_id IS NULL)
        UNION ALL
         SELECT ch.id,
            ch.parent_id,
            ch.name_en,
            ch.slug,
            ch.level,
            ch.path,
            (cp.breadcrumb_names || (ch.name_en)::text),
            (cp.breadcrumb_slugs || (ch.slug)::text),
            (cp.breadcrumb_ids || ch.id)
           FROM (public.category_hierarchy ch
             JOIN category_path cp ON ((ch.parent_id = cp.id)))
        )
 SELECT id,
    name_en,
    slug,
    level,
    breadcrumb_names,
    breadcrumb_slugs,
    breadcrumb_ids,
    array_length(breadcrumb_names, 1) AS depth
   FROM category_path;


ALTER VIEW public.category_breadcrumbs OWNER TO postgres;

--
-- Name: VIEW category_breadcrumbs; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.category_breadcrumbs IS 'Category with full breadcrumb path for navigation';


