--
-- Name: category_stats; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.category_stats AS
 SELECT ch.id,
    ch.id AS category_id,
    ch.parent_id,
    ch.name_en,
    ch.slug,
    ch.level,
    ch.is_leaf,
    count(p.id) AS product_count,
    count(p.id) FILTER (WHERE (p.status = 'approved'::public.product_status)) AS approved_count,
    count(p.id) FILTER (WHERE (p.status = 'pending'::public.product_status)) AS pending_count
   FROM (public.category_hierarchy ch
     LEFT JOIN public.products p ON ((p.category_hierarchy_id = ch.id)))
  GROUP BY ch.id, ch.parent_id, ch.name_en, ch.slug, ch.level, ch.is_leaf;


