    buyer_tier_expires_at timestamp with time zone,
    admin_role public.admin_role,
    otp_verified boolean DEFAULT false NOT NULL,
    is_banned boolean DEFAULT false NOT NULL,
    last_login_at timestamp with time zone,
    invited_by integer,
    invitation_accepted_at timestamp with time zone,
    referral_suspended boolean DEFAULT false NOT NULL,
    referral_permanently_blocked boolean DEFAULT false NOT NULL,
    referral_block_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    referral_code character varying(11) NOT NULL,
    seller_preference character varying(10) DEFAULT 'sale'::character varying,
    current_demand character varying(10),
    CONSTRAINT users_current_demand_check CHECK ((((current_demand)::text = ANY ((ARRAY['FIND'::character varying, 'LIST'::character varying])::text[])) OR (current_demand IS NULL))),
    CONSTRAINT users_seller_preference_check CHECK (((seller_preference)::text = ANY ((ARRAY['sale'::character varying, 'rent'::character varying, 'both'::character varying])::text[])))
);


