--
-- Name: marketplace_listings; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.marketplace_listings AS
 SELECT p.id,
    p.seller_id,
    p.title,
    p.price,
    p.rental_price_per_month,
    p.description,
    p.category_id,
    p.subcategory,
    p.item,
    p.condition,
    p.location_id,
    p.kebele,
    p.specific_area,
    p.latitude,
    p.longitude,
    p.listing_type,
    p.access_tier,
    p.seller_tier_snapshot,
    p.view_count,
    p.status,
    p.created_at,
    p.expires_at,
    u.name AS seller_name,
    u.rating AS seller_rating,
    u.business_name AS seller_business_name
   FROM (public.products p
     JOIN public.users u ON ((p.seller_id = u.id)))
  WHERE ((p.status = 'approved'::public.product_status) AND ((p.expires_at IS NULL) OR (p.expires_at > now())) AND (u.is_active = true) AND (u.is_banned = false))
  WITH NO DATA;


