--
-- Name: popular_searches; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.popular_searches AS
 SELECT normalized_query,
    count(*) AS search_count,
    avg(result_count) AS avg_results,
    count(clicked_product_id) AS clicks,
        CASE
            WHEN (count(*) > 0) THEN (((count(clicked_product_id))::double precision / (count(*))::double precision) * (100)::double precision)
            ELSE (0)::double precision
        END AS ctr_percent,
    max(created_at) AS last_searched
   FROM public.search_analytics
  WHERE (created_at >= (now() - '30 days'::interval))
  GROUP BY normalized_query
 HAVING (count(*) >= 3)
  ORDER BY (count(*)) DESC;


