--
-- Name: referral_commissions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.referral_commissions (
    id integer NOT NULL,
    referrer_id integer DEFAULT 0 NOT NULL,
    referred_id integer DEFAULT 0 NOT NULL,
    transaction_id integer,
    commission_amount numeric(12,2) DEFAULT 0 NOT NULL,
    commission_percent numeric(5,2) DEFAULT 0 NOT NULL,
    commission_rate numeric(5,2) DEFAULT 0,
    transaction_type character varying(50) DEFAULT ''::character varying NOT NULL,
    transaction_amount numeric(12,2) DEFAULT 0,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    confirmed_at timestamp with time zone,
