--
-- Name: seller_profit_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.seller_profit_summary AS
 SELECT seller_id,
    COALESCE(( SELECT sum(t.amount) AS sum
           FROM public.transactions t
          WHERE ((t.seller_id = p.seller_id) AND ((t.status)::text = 'completed'::text))), (0)::numeric) AS total_revenue,
    COALESCE(sum(total_fee_amount) FILTER (WHERE (fee_paid = true)), (0)::numeric) AS total_fees_paid,
    (COALESCE(( SELECT sum(t.amount) AS sum
           FROM public.transactions t
          WHERE ((t.seller_id = p.seller_id) AND ((t.status)::text = 'completed'::text))), (0)::numeric) - COALESCE(sum(total_fee_amount) FILTER (WHERE (fee_paid = true)), (0)::numeric)) AS net_profit
   FROM public.products p
  GROUP BY seller_id;


ALTER VIEW public.seller_profit_summary OWNER TO postgres;

--
-- Name: VIEW seller_profit_summary; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.seller_profit_summary IS 'Per-seller financial summary: total_revenue, total_fees_paid, net_profit. Used by seller dashboard stats endpoint.';


