    round(avg(rating), 2) AS avg_rating,
    count(*) FILTER (WHERE (rating >= (4)::numeric)) AS positive_reviews,
    count(*) FILTER (WHERE (rating <= (2)::numeric)) AS negative_reviews,
    max(created_at) AS last_review_date
   FROM public.seller_reviews
  GROUP BY seller_id
  WITH NO DATA;


