--
-- Name: user_capabilities_view _RETURN; Type: RULE; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW public.user_capabilities_view AS
 SELECT u.id AS user_id,
    u.name,
    u.phone,
    u.email,
    u.role,
    u.tier AS seller_tier,
    u.buyer_tier,
    u.admin_role,
    u.is_active,
    COALESCE(array_agg(uc.capability) FILTER (WHERE ((uc.status)::text = 'active'::text)), ARRAY['buyer'::character varying]) AS active_capabilities
   FROM (public.users u
     LEFT JOIN public.user_capabilities uc ON ((uc.user_id = u.id)))
  GROUP BY u.id;


